function compress(input) {
    if (!input) return "";
    let result = "";
    let count = 1;
    for (let i = 1; i <= input.length; i++) {
        if (i < input.length && input[i] === input[i - 1]) {
            count++;
        } else {
            result += input[i - 1];
            if (count > 1) {
                result += count;
            }
            count = 1;
        }
    }
    return result;
}

